use vstd::prelude::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> Vec<u64>
    requires
        a.len() <= 100,
        b.len() <= 100,
    ensures
        result.len() == a.len() + b.len(),
        forall|i: usize| (i < a.len() ==> result[i] == a[i]),
        forall|i: usize| (a.len() <= i && i < result.len() ==> result[i] == b[i - a.len()])
{
    let mut result: Vec<u64> = Vec::new();
    result.reserve(a.len() + b.len());

    // Append all elements from a
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|j: usize| (j < i ==> result[j] == a[j]),
        decreases a.len() - i,
    {
        result.push(a[i]);
        i = i + 1;
    }

    // Append all elements from b
    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b.len(),
            result.len() == a.len() + j,
            forall|k: usize| (k < a.len() ==> result[k] == a[k]),
            forall|k: usize| (a.len() <= k && k < a.len() + j ==> result[k] == b[k - a.len()]),
        decreases b.len() - j,
    {
        result.push(b[j]);
        j = j + 1;
    }

    result
}

}
